# Generated by Descant: acceptance tests.

require "spec_helper"
require_relative "../../../../spec/support/timekeeping/fake_relay"

RSpec.describe TimekeepingRelaySpec::FakeRelayEndpoint do
  # The 403 must come from the real consumer fake's credential check, not from a script,
  # so the endpoint is built with no scripted answers.
  it "a credential without the deliver operation gets the consumer's 403, recorded in posts, and projects nothing" do
    timekeeping = TimekeepingContract::FakeTimekeeping.new
    credential = timekeeping.add_service(company_id: nil, name: "reporting", operations: ["read"])
    projection = TimekeepingContract::FakeRelay.new(source: timekeeping)
    endpoint = described_class.new(projection:, credential:)
    batch = { "schema_version" => 1, "snapshots" => [TimekeepingRelaySpec::MemoryOutboxSource.row(4)] }

    response = endpoint.deliver(batch, idempotency_key: "key-403")

    expect(response.status).to eq(403)
    expect(response.delivered?(1)).to be(false)
    expect(endpoint.posts.size).to eq(1)
    expect(endpoint.posts.first[:key]).to eq("key-403")
    expect(endpoint.posts.first[:answer].status).to eq(403)
    expect(projection.projected_entry(4)).to be_nil
  end
end
